use cxx_qt_build::{CxxQtBuilder, PluginType, QmlModule};
use std::{env, fs, path::PathBuf};

fn main() {
    CxxQtBuilder::new_qml_module(
        QmlModule::new("C7Spike")
            .version(1, 0)
            .plugin_type(PluginType::Dynamic),
    )
    .files(["src/bridge.rs"])
    .build();

    // A Rust cdylib hides every symbol it did not define in Rust (rustc's own
    // version script ends in `local: *`), and --gc-sections then drops them.
    // Qt finds a plugin by its two C entry points, generated by moc from
    // Q_PLUGIN_METADATA, so they must stay global. This is a linker input, not C++.
    //
    // It needs gold or lld. GNU ld.bfd refuses a second version script next to
    // rustc's anonymous one ("anonymous version tag cannot be combined with
    // other version tags"), named or not, and --dynamic-list /
    // --export-dynamic-symbol cannot override rustc's `local: *`. So
    // .cargo/config.toml pins rust-lld (README, check 8).
    let map = PathBuf::from(env::var("OUT_DIR").unwrap()).join("qt_plugin_exports.map");
    fs::write(&map, "{\n  global:\n    qt_plugin_instance;\n    qt_plugin_query_metadata_v2;\n};\n").unwrap();
    println!("cargo::rustc-cdylib-link-arg=-Wl,--version-script={}", map.display());
}
